package com.macamara.app;
import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.os.*;import android.view.Surface;import androidx.camera.core.*;import androidx.camera.lifecycle.ProcessCameraProvider;import androidx.camera.video.*;import androidx.camera.view.PreviewView;import androidx.core.app.NotificationCompat;import androidx.core.content.ContextCompat;import androidx.lifecycle.LifecycleService;import com.google.common.util.concurrent.ListenableFuture;import java.io.File;import java.lang.ref.WeakReference;import java.util.concurrent.*;
public class RecordingService extends LifecycleService{
 public static final String ACTION_START="com.macamara.START",ACTION_STOP="com.macamara.STOP";public static volatile boolean isRecording=false;public static volatile String currentSegmentName="none";
 private static WeakReference<PreviewView> previewRef=new WeakReference<>(null);
 final Handler h=new Handler(Looper.getMainLooper());final ExecutorService ex=Executors.newSingleThreadExecutor();Recording recording;Recorder recorder;VideoCapture<Recorder> capture;Preview preview;boolean stopping;long segmentStart;MemoryStore db;
 public static void attachPreview(PreviewView v){previewRef=new WeakReference<>(v);if(instance!=null)instance.connectPreview();}
 public static void detachPreview(PreviewView v){PreviewView current=previewRef.get();if(current==v){previewRef.clear();if(instance!=null&&instance.preview!=null)instance.preview.setSurfaceProvider(null);}}
 private static RecordingService instance;
 public void onCreate(){super.onCreate();instance=this;db=new MemoryStore(this);channel();}
 public int onStartCommand(Intent i,int f,int id){super.onStartCommand(i,f,id);if(i!=null&&ACTION_STOP.equals(i.getAction())){stopping=true;isRecording=false;stopClip();stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();}else if(i!=null&&ACTION_START.equals(i.getAction())&&!isRecording){stopping=false;startForeground(17,notification());camera();}return START_STICKY;}
 void camera(){ListenableFuture<ProcessCameraProvider> fu=ProcessCameraProvider.getInstance(this);fu.addListener(()->{try{ProcessCameraProvider p=fu.get();p.unbindAll();recorder=new Recorder.Builder().setQualitySelector(QualitySelector.from(Quality.FHD)).build();capture=VideoCapture.withOutput(recorder);preview=new Preview.Builder().setTargetRotation(Surface.ROTATION_0).build();connectPreview();p.bindToLifecycle(this,CameraSelector.DEFAULT_BACK_CAMERA,preview,capture);startClip();}catch(Exception e){isRecording=false;stopSelf();}},ContextCompat.getMainExecutor(this));}
 void connectPreview(){if(preview==null)return;PreviewView v=previewRef.get();if(v!=null)preview.setSurfaceProvider(v.getSurfaceProvider());}
 void startClip(){if(stopping||capture==null)return;File d=new File(getExternalFilesDir(null),"Memory");d.mkdirs();File file=new File(d,"MEMORY_"+System.currentTimeMillis()+".mp4");currentSegmentName=file.getName();segmentStart=System.currentTimeMillis();FileOutputOptions out=new FileOutputOptions.Builder(file).build();recording=recorder.prepareRecording(this,out).withAudioEnabled().start(ContextCompat.getMainExecutor(this),e->{if(e instanceof VideoRecordEvent.Finalize){VideoRecordEvent.Finalize x=(VideoRecordEvent.Finalize)e;long end=System.currentTimeMillis();recording=null;if(x.getError()==VideoRecordEvent.Finalize.ERROR_NONE&&!stopping){long cid=db.addClip(file.getAbsolutePath(),segmentStart,end);ClipAnalyzer.analyze(this,cid,file,db);h.postDelayed(this::startClip,250);}}});isRecording=true;h.postDelayed(()->{if(!stopping&&recording!=null){Recording r=recording;recording=null;r.stop();}},120000);}
 void stopClip(){h.removeCallbacksAndMessages(null);if(recording!=null){Recording r=recording;recording=null;r.stop();}}
 Notification notification(){return new NotificationCompat.Builder(this,"mc").setSmallIcon(android.R.drawable.ic_menu_camera).setContentTitle("MA CAMARA").setContentText("Visible camera recording is active").setOngoing(true).setCategory(NotificationCompat.CATEGORY_SERVICE).build();}
 void channel(){if(Build.VERSION.SDK_INT>=26)getSystemService(NotificationManager.class).createNotificationChannel(new NotificationChannel("mc","MA CAMARA recording",NotificationManager.IMPORTANCE_LOW));}
 public void onDestroy(){stopping=true;isRecording=false;stopClip();if(preview!=null)preview.setSurfaceProvider(null);if(instance==this)instance=null;ex.shutdownNow();super.onDestroy();}
}